// Valida dono, status e antecedência mínima de 2h (§4).
const args = $input.first().json || {};
const row = $('Buscar Agendamento para Cancelar').first().json || null;
if (!row) return [{ json: { ok: false, policy_violation: false, reason: 'agendamento-nao-encontrado' } }];
if (row.wa_id !== args.wa_id) return [{ json: { ok: false, policy_violation: false, reason: 'nao-autorizado', appointment_id: row.id } }];
if (!['scheduled', 'confirmed'].includes(row.status)) return [{ json: { ok: false, policy_violation: false, reason: 'status-nao-permite-cancelamento', appointment_id: row.id } }];
const limite = new Date(Date.now() + 2 * 3600 * 1000); // CANCEL_MIN_HOURS=2
if (new Date(row.start_at) < limite) {
  return [{ json: { ok: false, policy_violation: true, reason: 'Cancelamento exige 2h de antecedência', appointment_id: row.id } }];
}
return [{ json: { ok: true, policy_violation: false, reason: null, appointment_id: row.id, motivoCancel: args.reason || 'Cancelado pelo cliente' } }];
